-- BIOTICWAW 1.4.x · the 26 antibiotic sources (exported from the TEST project on 2026-11-09, all reviewed there).
-- Run on LIVE at release, after the antibiotic migrations (2026110911…–2026110922…). Safe to run twice.
-- Old sources with other ids (the vitamin era) are soft-deleted (deleted = true), never removed.
on conflict (id) do update set org = excluded.org, title = excluded.title, url = excluded.url, use_ar = excluded.use_ar,
  use_en = excluded.use_en, kind = excluded.kind, reviewed = true, reviewed_at = now(), deleted = false, hidden = false, updated_at = now();
update public.sources set reviewed = true, reviewed_at = coalesce(reviewed_at, now()) where id between 1 and 26;
-- the vitamin-era sources: soft delete (kept for history)
update public.sources set deleted = true, updated_at = now() where id > 26 and not deleted;
